		private static Task SendReadyForPlayScreen(INetworkClient client)
		{
			var sender = client.Session.Character?.Name == null
				? NewCharacterReadyForPlayScreenSender
				: ExistingCharacterReadyForPlayScreenSender;
			var receiver = client.Session.Character?.Name == null
				? NewCharacterReadyForPlayScreenReceiver
				: AppendVarint(ExistingCharacterReadyForPlayScreenReceiverPrefix, client.Session.Account.ClientInstance);

			if (client.Session.Character?.Name == null)
			{
				// New-character create flow (unchanged): pos1 twice + the create tail.
				byte[] newTail =
				[
					0x00, 0x00, 0xC7, 0x9E,
					0x00, 0x00, 0x0F, 0xAA,
					0x00, 0x00, 0x00, 0x00,
					0x00, 0x00, 0x00, 0x00,
					0x00, 0x00, 0x00, 0x00,
					0x00, 0x00, 0x00, 0x00,
					0x00, 0x64,
					0x00
				];

				return new PacketStream()
					.WriteHeader(sender, receiver, GameServerRespondOpcodes.ReadyForPlayScreen)
					.WriteVector3BigEndian(client.Session.Character!.Position)
					.WriteUInt32(0x000007E2)
					.WriteVector3BigEndian(client.Session.Character.Position)
					.WriteArray(newTail)
					.SendAsync(client);
			}

			// Existing-character login: emit pos1 (the character's live position) + 0x7E2 + pos2 + tail EXACTLY as
			// the Strie 4010 capture (idx 236). The old code wrote pos2 = pos1 and a nibble-shifted tail constant
			// (0BF76C -> BF76C0), so the client got a malformed ReadyForPlayScreen and ignored it. pos2 and the tail
			// are taken verbatim from the capture (the map-4010 "ready" point); if they turn out to be per-map they
			// move to the Map row later.
			byte[] pos2AndTail =
			[
				// pos2 = (336.309, 148.967, 660.968) BE
				0x43, 0xA8, 0x27, 0x8D, 0x43, 0x14, 0xF7, 0x8D, 0x44, 0x25, 0x3D, 0xF4,
				// tail
				0x00, 0x00, 0xC7, 0xA0,
				0x00, 0x00, 0x0F, 0xAA,
				0x00, 0x00, 0x00, 0x00,
				0x00, 0x00, 0x00, 0x00,
				0x00, 0x00, 0x00, 0x00,
				0x00, 0x0B, 0xF7, 0x6C,
				0x00, 0x00, 0x00, 0x0A,
				0x00
			];

			return new PacketStream()
				.WriteHeader(sender, receiver, GameServerRespondOpcodes.ReadyForPlayScreen)
				.WriteVector3BigEndian(client.Session.Character!.Position)
				.WriteUInt32(0x000007E2)
				.WriteArray(pos2AndTail)
				.SendAsync(client);
		}

		private static Task SetTimeOfDay(INetworkClient client)
		{
			var sender0 = LoginWorldSender;
			var receiver0 = LoginWorldReceiver(client);

			return new PacketStream()
				.WriteHeader(sender0, receiver0, 0x2000)
				.WriteArrayUInt32Length(s => s
					.WriteUInt32(GameServer0X2000RespondsOpcodes.SetDayTime)
					/*.WriteArray(
					    0x00, 0x00, 0x00, 0x00,
					    0x00, 0x00, 0x00, 0x00,
					    0x01, 0x46, 0xA8, 0xD8,
					    0x00, 0x00, 0x00, 0x00,
					    0x03,
					    0x00, 0x01, 0x42, 0x10,
					    0x54, 0xEB, 0x48, 0xD4,
					    0x3F, 0x80)*/
					.WriteArray(0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x47, 0x59, 0x92, 0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x01, 0x6C, 0xD7, 0x60, 0x32, 0xDC, 0x20, 0x3F, 0x80, 0x00, 0x00))
				.SendAsync(client);
		}

		// The captured post-ready A36D tails embed the old session instance (0x01307874 = F4 F0 C1 09) as a
		// nested protobuf varint. Replace it with the live instance (length-preserving for a 4-byte-varint id).
		private static byte[] SubstitutePostReadyInstance(byte[] tail, uint instance)
		{
			var placeholder = new byte[] { 0xF4, 0xF0, 0xC1, 0x09 };
			var inst = EncodeVarint(instance);
			if (inst.Length != placeholder.Length)
				return tail;

			var result = (byte[])tail.Clone();
			for (var i = 0; i <= result.Length - placeholder.Length; i++)
			{
				if (result[i] == placeholder[0] && result[i + 1] == placeholder[1] && result[i + 2] == placeholder[2] && result[i + 3] == placeholder[3])
				{
					Array.Copy(inst, 0, result, i, inst.Length);
					i += placeholder.Length - 1;
				}
			}

			return result;
		}
	}
